<?php
namespace ExcelHerbal\ERP7\Finance;
use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Inventory\StockService;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class FinanceReversalService{
 public static function reversals(Actor $a,string $status=''):array{
  Guard::any($a,[Capabilities::REVERSAL_CREATE,Capabilities::REVERSAL_APPROVE]);
  $db=Db::wpdb();
  $branchIds=array_values(array_unique(array_filter(array_map('intval',$a->branchIds),static fn(int $id):bool=>$id>0)));
  $active=(array)$db->get_col($db->prepare("SELECT id FROM ".Db::table('branches')." WHERE company_id=%d AND status='active'",$a->companyId));
  $allActive=count($active)>0&&count(array_diff(array_map('intval',$active),$branchIds))===0;
  $scope=[];$args=[$a->companyId];
  if($branchIds){
   $scope[]='branch_id IN ('.implode(',',array_fill(0,count($branchIds),'%d')).')';
   $args=array_merge($args,$branchIds);
  }
  // Company-wide reversals must not leak into branch-limited lists.
  if($allActive)$scope[]='branch_id IS NULL';
  if(!$scope)return[];
  $sql="SELECT * FROM ".Db::table('reversals')." WHERE company_id=%d AND (".implode(' OR ',$scope).")";
  if($status!==''){$sql.=' AND status=%s';$args[]=$status;}
  $sql.=' ORDER BY id DESC LIMIT 200';
  return(array)$db->get_results($db->prepare($sql,...$args),ARRAY_A);
 }
 public static function requestReversal(Actor $a,string $type,int $source,string $reason):array{Guard::cap($a,Capabilities::REVERSAL_CREATE);$allowed=['counter_sale','purchase_bill','supplier_payment','customer_receipt','expense','daily_cycle','stock_adjustment','payroll','payroll_payment'];if(!in_array($type,$allowed,true)||$source<1||strlen(trim($reason))<5)throw new DomainException('Valid source and reason required.');return Transaction::run(function()use($a,$type,$source,$reason){$db=Db::wpdb();$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','daily_cycle'=>'daily_cycles','stock_adjustment'=>'stock_adjustments','payroll'=>'payroll_runs','payroll_payment'=>'payroll_runs'];$sourceRow=$db->get_row($db->prepare("SELECT * FROM ".Db::table($map[$type])." WHERE id=%d AND company_id=%d FOR UPDATE",$source,$a->companyId),ARRAY_A);if(!$sourceRow)throw new DomainException('Reversal source not found.','reversal_source_not_found',404);$branch=$sourceRow['branch_id']!==null?(int)$sourceRow['branch_id']:null;if($branch)Guard::branch($a,$branch,Capabilities::REVERSAL_CREATE);else Guard::allActiveBranches($a,Capabilities::REVERSAL_CREATE);$status=(string)$sourceRow['status'];$required=in_array($type,['expense','stock_adjustment','payroll'],true)?'approved':($type==='payroll_payment'?'paid':($type==='daily_cycle'?'completed':'posted'));if($status!==$required)throw new DomainException('Only a currently posted/approved source can be reversed.','reversal_source_state_invalid',409);$active=(int)$db->get_var($db->prepare("SELECT id FROM ".Db::table('reversals')." WHERE company_id=%d AND source_type=%s AND source_id=%d AND status IN ('pending','approved') ORDER BY id DESC LIMIT 1 FOR UPDATE",$a->companyId,$type,$source));if($active)throw new DomainException('An active reversal request already exists for this source.','reversal_already_pending',409);Db::mustInsert($db,Db::table('reversals'),['company_id'=>$a->companyId,'branch_id'=>$branch,'source_type'=>$type,'source_id'=>$source,'reason'=>trim($reason),'status'=>'pending','requested_by'=>$a->employeeId,'requested_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'reversal.request','reversal',$id,['branch_id'=>$branch,'source_type'=>$type,'source_id'=>$source]);return['id'=>$id,'status'=>'pending'];});}
 public static function reversalDecision(Actor $a,int $id,bool $approve):array{
  Guard::cap($a,Capabilities::REVERSAL_APPROVE);
  return Transaction::run(function()use($a,$id,$approve){
   $db=Db::wpdb();$t=Db::table('reversals');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Reversal not found.');if($r['branch_id'])Guard::branch($a,(int)$r['branch_id'],Capabilities::REVERSAL_APPROVE);else Guard::allActiveBranches($a,Capabilities::REVERSAL_APPROVE);if($r['status']!=='pending')throw new DomainException('Reversal not pending.');if((int)$r['requested_by']===$a->employeeId)throw new DomainException('Maker cannot approve own reversal.','maker_checker_required',409);$status=$approve?'approved':'rejected';Db::mustUpdate($db,$t,['status'=>$status,'decided_by'=>$a->employeeId,'decided_at'=>Db::now()],['id'=>$id]);Audit::add($a,'reversal.'.($approve?'approve':'reject'),'reversal',$id,['branch_id'=>$r['branch_id'],'source_type'=>$r['source_type'],'source_id'=>(int)$r['source_id']]);return['id'=>$id,'status'=>$status];
  });
 }
 public static function executeReversal(Actor $a,int $id):array{Guard::cap($a,Capabilities::REVERSAL_APPROVE);return Transaction::run(function()use($a,$id){$db=Db::wpdb();$t=Db::table('reversals');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r||$r['status']!=='approved')throw new DomainException('Approved reversal not found.');if($r['branch_id']){Guard::branch($a,(int)$r['branch_id'],Capabilities::REVERSAL_APPROVE);if((string)$r['source_type']!=='daily_cycle')BranchDayGuard::assertOpen($a,(int)$r['branch_id'],Db::today());}else Guard::allActiveBranches($a,Capabilities::REVERSAL_APPROVE);$type=(string)$r['source_type'];$source=(int)$r['source_id'];$required=in_array($type,['expense','stock_adjustment','payroll'],true)?'approved':($type==='payroll_payment'?'paid':($type==='daily_cycle'?'completed':'posted'));if(self::sourceStatus($a,$type,$source)!==$required)throw new DomainException('Reversal source state changed after request. Create a new reversal request.','reversal_source_state_changed',409);$journalId=self::sourceJournal($a,$type,$source);if(!$journalId)throw new DomainException('Source journal missing.','source_journal_missing',409);if($type==='counter_sale')self::reverseCounterStock($a,$source);elseif($type==='purchase_bill')self::reversePurchaseStock($a,$source);elseif($type==='supplier_payment')self::reverseSupplierPayment($a,$source);elseif($type==='customer_receipt')self::reverseCustomerReceipt($a,$source);elseif($type==='daily_cycle')self::reverseDailyCycle($a,$source,$id);elseif($type==='stock_adjustment')self::reverseStockAdjustment($a,$source,$id);$rev=AccountingService::reverse($a,$journalId,(string)$r['reason'],$id);self::markSourceReversed($type,$source);Db::mustUpdate($db,$t,['status'=>'executed','executed_by'=>$a->employeeId,'executed_at'=>Db::now()],['id'=>$id]);Audit::add($a,'reversal.execute','reversal',$id,['branch_id'=>$r['branch_id'],'source_type'=>$type,'source_id'=>$source]);return['id'=>$id,'status'=>'executed','reversal_journal_id'=>$rev];});}
 private static function sourceBranch(Actor $a,string $type,int $id):?int{$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','daily_cycle'=>'daily_cycles','stock_adjustment'=>'stock_adjustments','payroll'=>'payroll_runs','payroll_payment'=>'payroll_runs'];$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT branch_id FROM ".Db::table($map[$type])." WHERE id=%d AND company_id=%d",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Reversal source not found.');return$r['branch_id']!==null?(int)$r['branch_id']:null;}
 private static function sourceStatus(Actor $a,string $type,int $id):string{$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','daily_cycle'=>'daily_cycles','stock_adjustment'=>'stock_adjustments','payroll'=>'payroll_runs','payroll_payment'=>'payroll_runs'];$db=Db::wpdb();$status=$db->get_var($db->prepare("SELECT status FROM ".Db::table($map[$type])." WHERE id=%d AND company_id=%d",$id,$a->companyId));if($status===null)throw new DomainException('Reversal source not found.','reversal_source_not_found',404);return(string)$status;}
 private static function sourceJournal(Actor $a,string $type,int $id):int{$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','stock_adjustment'=>'stock_adjustments','payroll'=>'payroll_runs','payroll_payment'=>'payroll_runs'];if($type==='daily_cycle')return(int)Db::wpdb()->get_var(Db::wpdb()->prepare("SELECT id FROM ".Db::table('journal_entries')." WHERE company_id=%d AND source_type='daily_cycle' AND source_id=%d AND status='posted'",$a->companyId,$id));if($type==='payroll_payment')return(int)Db::wpdb()->get_var(Db::wpdb()->prepare("SELECT payment_journal_entry_id FROM ".Db::table('payroll_runs')." WHERE id=%d AND company_id=%d",$id,$a->companyId));return(int)Db::wpdb()->get_var(Db::wpdb()->prepare("SELECT journal_entry_id FROM ".Db::table($map[$type])." WHERE id=%d AND company_id=%d",$id,$a->companyId));}
 private static function markSourceReversed(string $type,int $id):void{$db=Db::wpdb();if($type==='payroll_payment'){Db::mustUpdate($db,Db::table('payroll_runs'),['status'=>'approved','payment_account_id'=>null,'payment_journal_entry_id'=>null,'payment_date'=>null,'paid_by'=>null,'paid_at'=>null],['id'=>$id]);return;}if($type==='payroll'){Db::mustUpdate($db,Db::table('payroll_runs'),['status'=>'draft','approved_by'=>null,'journal_entry_id'=>null,'approved_at'=>null],['id'=>$id]);return;}$map=['counter_sale'=>'counter_sales','purchase_bill'=>'purchase_bills','supplier_payment'=>'supplier_payments','customer_receipt'=>'customer_receipts','expense'=>'expenses','stock_adjustment'=>'stock_adjustments'];if(isset($map[$type]))Db::mustUpdate($db,Db::table($map[$type]),['status'=>'reversed'],['id'=>$id]);}
 private static function reverseCounterStock(Actor $a,int $id):void{$db=Db::wpdb();$sale=$db->get_row($db->prepare("SELECT * FROM ".Db::table('counter_sales')." WHERE id=%d AND company_id=%d AND status='posted'",$id,$a->companyId),ARRAY_A);if(!$sale)throw new DomainException('Posted Counter Sale not found.');$allocated=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('customer_receipts')." WHERE sale_id=%d AND company_id=%d AND status='posted'",$id,$a->companyId));if($allocated)throw new DomainException('Reverse allocated customer receipts before sale.','dependent_receipt_exists',409);foreach((array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('counter_sale_lines')." WHERE sale_id=%d",$id),ARRAY_A) as$l)StockService::move($a,(int)$sale['branch_id'],(int)$l['product_id'],$l['batch_id']!==null?(int)$l['batch_id']:null,null,'IN',(float)$l['quantity'],(float)$l['purchase_cost_snapshot'],'counter_sale_reversal',$id);}
 private static function reversePurchaseStock(Actor $a,int $id):void{$db=Db::wpdb();
  // Supplier payments lock the same bill row before posting. Hold that lock
  // through the dependency check, stock OUT, GL reversal and status update.
  $bill=$db->get_row($db->prepare("SELECT * FROM ".Db::table('purchase_bills')." WHERE id=%d AND company_id=%d AND status='posted' FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$bill)throw new DomainException('Posted Purchase Bill not found.');if((float)$bill['paid_amount']>0||(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('supplier_payments')." WHERE company_id=%d AND purchase_bill_id=%d AND status='posted'",$a->companyId,$id))>0)throw new DomainException('Reverse all posted supplier payments before purchase bill.','dependent_payment_exists',409);if(abs((float)$bill['paid_amount'])>.005||abs((float)$bill['outstanding_amount']-(float)$bill['total_amount'])>.005)throw new DomainException('Supplier bill payment balance must reconcile before full reversal.','purchase_bill_settlement_mismatch',409);foreach((array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('purchase_bill_lines')." WHERE purchase_bill_id=%d",$id),ARRAY_A) as$l)StockService::move($a,(int)$bill['branch_id'],(int)$l['product_id'],$l['batch_id']!==null?(int)$l['batch_id']:null,null,'OUT',(float)$l['quantity'],(float)$l['unit_cost'],'purchase_bill_reversal',$id);}
 private static function reverseSupplierPayment(Actor $a,int $id):void{$db=Db::wpdb();$t=Db::table('supplier_payments');$p=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d AND status='posted' FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$p)throw new DomainException('Posted Supplier Payment not found.');Db::mustQuery($db,$db->prepare("UPDATE ".Db::table('purchase_bills')." SET paid_amount=paid_amount-%f,outstanding_amount=outstanding_amount+%f WHERE id=%d",(float)$p['amount'],(float)$p['amount'],(int)$p['purchase_bill_id']));}
 private static function reverseCustomerReceipt(Actor $a,int $id):void{$db=Db::wpdb();$t=Db::table('customer_receipts');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d AND status='posted' FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Posted Customer Receipt not found.');$sale=$db->get_row($db->prepare("SELECT id,paid_amount,outstanding_amount FROM ".Db::table('counter_sales')." WHERE id=%d AND company_id=%d AND status='posted' FOR UPDATE",(int)$r['sale_id'],$a->companyId),ARRAY_A);if(!$sale)throw new DomainException('Receipt source sale is not posted.','receipt_sale_state_invalid',409);$amount=(float)$r['amount'];if((float)$sale['paid_amount']+.005<$amount)throw new DomainException('Receipt reversal would make sale payment invalid.','receipt_reversal_invalid',409);Db::mustQuery($db,$db->prepare("UPDATE ".Db::table('counter_sales')." SET paid_amount=paid_amount-%f,outstanding_amount=outstanding_amount+%f WHERE id=%d",$amount,$amount,(int)$r['sale_id']));}
 private static function reverseStockAdjustment(Actor $a,int $adjustmentId,int $reversalId):void{$db=Db::wpdb();$h=Db::table('stock_adjustments');$r=$db->get_row($db->prepare("SELECT * FROM {$h} WHERE id=%d AND company_id=%d AND status='approved' FOR UPDATE",$adjustmentId,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Approved Stock Adjustment not found.','adjustment_not_found',404);$lines=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('stock_adjustment_lines')." WHERE adjustment_id=%d ORDER BY id",$adjustmentId),ARRAY_A);foreach($lines as$l){$d=(float)$l['quantity_delta'];$batch=$l['batch_id']!==null?(int)$l['batch_id']:null;$cost=(float)$l['unit_cost_snapshot'];StockService::move($a,(int)$r['branch_id'],(int)$l['product_id'],$batch,null,$d>0?'OUT':'IN',abs($d),$cost,'stock_adjustment_reversal',$reversalId);}}
 private static function reverseDailyCycle(Actor $a,int $cycleId,int $reversalId):void{$db=Db::wpdb();$c=$db->get_row($db->prepare("SELECT * FROM ".Db::table('daily_cycles')." WHERE id=%d AND company_id=%d AND status='completed' FOR UPDATE",$cycleId,$a->companyId),ARRAY_A);if(!$c)throw new DomainException('Completed Daily Order not found.');$closed=(string)$db->get_var($db->prepare("SELECT status FROM ".Db::table('branch_closings')." WHERE company_id=%d AND branch_id=%d AND business_date=%s",$a->companyId,(int)$c['branch_id'],$c['business_date']));if($closed==='closed')throw new DomainException('Reopen Branch Closing before Daily Order correction.','branch_day_closed',409);$e=$db->get_row($db->prepare("SELECT * FROM ".Db::table('evening_settlements')." WHERE daily_cycle_id=%d FOR UPDATE",$cycleId),ARRAY_A);if(!$e||$e['status']!=='posted')throw new DomainException('Posted Evening Settlement not found.');$lines=(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('evening_lines')." WHERE evening_settlement_id=%d",(int)$e['id']),ARRAY_A);foreach($lines as$l){$batch=$l['batch_id']!==null?(int)$l['batch_id']:null;$sold=(float)$l['retail_quantity']+(float)$l['wholesale_quantity'];$ret=(float)$l['return_quantity'];$cost=(float)$l['purchase_cost_snapshot'];if($sold>0)StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,(int)$c['employee_id'],'IN',$sold,$cost,'daily_sale_reversal',$reversalId);if($ret>0){StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,null,'OUT',$ret,$cost,'daily_return_reversal',$reversalId);StockService::move($a,(int)$c['branch_id'],(int)$l['product_id'],$batch,(int)$c['employee_id'],'IN',$ret,$cost,'daily_return_reversal',$reversalId);}}$points=(float)$db->get_var($db->prepare("SELECT COALESCE(SUM(points),0) FROM ".Db::table('performance_entries')." WHERE company_id=%d AND employee_id=%d AND source_type='daily_cycle' AND source_id=%d",$a->companyId,(int)$c['employee_id'],$cycleId));$salary=(float)$db->get_var($db->prepare("SELECT COALESCE(SUM(salary_fund),0) FROM ".Db::table('performance_entries')." WHERE company_id=%d AND employee_id=%d AND source_type='daily_cycle' AND source_id=%d",$a->companyId,(int)$c['employee_id'],$cycleId));Db::mustInsert($db,Db::table('performance_entries'),['company_id'=>$a->companyId,'branch_id'=>(int)$c['branch_id'],'employee_id'=>(int)$c['employee_id'],'business_date'=>$c['business_date'],'source_type'=>'daily_cycle_reversal','source_id'=>$reversalId,'points'=>-$points,'salary_fund'=>-$salary,'created_at'=>Db::now()]);Db::mustUpdate($db,Db::table('evening_settlements'),['status'=>'draft','cash_amount'=>0,'upi_amount'=>0,'submitted_by'=>null,'reviewed_by'=>null,'submitted_at'=>null,'reviewed_at'=>null],['id'=>(int)$e['id']]);Db::mustUpdate($db,Db::table('daily_cycles'),['status'=>'evening_draft','completed_at'=>null],['id'=>$cycleId]);}
}
